describe("doctests of sympy.sets.conditionset", () => {
  // a primitive result that no library call returned
  //   2*pi in sin_sols
  //   => True
  it.todo("2*pi in sin_sols");
  it("pi/2 in sin_sols", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("3*pi in sin_sols", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  // a primitive result that no library call returned
  //   5 in ConditionSet(x, x**2 > 4, S.Reals)
  //   => True
  it.todo("5 in ConditionSet(x, x**2 > 4, S.Reals)");
  it("5 in ConditionSet(x, x**2 > 4, Interval(2, 4))", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("ConditionSet(n, cond, S.Integers)", () => {
    const n = new Sym('n', { negative: true });
    expect(sympyStr(ConditionSet.of(n, S['false'], Integers))).toBe('EmptySet');
  });
  it("c.subs(x, y)", () => {
    const [x, z, y] = symbols('x z y');
    expect(sympyStr(new ConditionSet(x, rel('Lt', x, 1), finiteSet(x, z)).subs(x, y))).toBe('ConditionSet(x, x < 1, {y, z})');
  });
  it("pi in c", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("ConditionSet(x, x < 1).base_set", () => {
    expect(sympyStr(UniversalSet)).toBe('UniversalSet');
  });
  it("ConditionSet(x, x < y, ConditionSet(z, z + y < 2, S.Integers))", () => {
    const [x, y, z] = symbols('x y z');
    expect(sympyStr(ConditionSet.of(x, rel('Lt', x, y), new ConditionSet(z, rel('Lt', add(y, z), 2), Integers)))).toBe('ConditionSet(x, (x < y) & (x + y < 2), Integers)');
  });
});

